import {foods,recipes} from './data.js';
import {days,slots,foodNames,cuisineNames,blankProfile,calculateEnergy,planWeek,shoppingList,completeness,validateImportedProfile,unitOf} from './engine.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const round=(n,step=1)=>Math.round(n/step)*step;
const format=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:0}).format(n);
const storageKey='recipe-assistant:profile:v1';
let profile=blankProfile(),plan=null,selectedDay=0,seed=0,currentView='profil',catalog=null,recipeLimit=30,checkedShopping=new Set(),savedEnabled=false;
const state={food:{},cuisine:{},visited:new Set([1])};
const dietLabels=[['Allesesser','Fleisch, Fisch und pflanzliche Lebensmittel'],['Flexitarisch','Überwiegend pflanzlich, gelegentlich Fleisch/Fisch'],['Pescetarisch','Vegetarisch plus Fisch und Meeresfrüchte'],['Vegetarisch','Kein Fleisch und kein Fisch'],['Vegan','Keine tierischen Lebensmittel'],['Ayurvedisch','Zusätzliche kulinarische/traditionelle Ausrichtung']];
const allergens=['Keine bekannt','Glutenhaltiges Getreide','Krebstiere','Eier','Fisch','Erdnüsse','Soja','Milch','Schalenfrüchte / Nüsse','Sellerie','Senf','Sesam','Sulfite / Schwefeldioxid','Lupinen','Weichtiere'];
const sportLevels=[['Geringe Intensität','gemütliches Radfahren, leichtes Yoga, entspanntes Schwimmen'],['Mittlere Intensität','Aerobic, Inlineskaten, Tennis'],['Hohe Intensität','Joggen, intensives Krafttraining, Intervalltraining']];
const options=values=>values.map(v=>`<option>${esc(v)}</option>`).join('');
const choice=(type,name,value,label)=>`<label class="ra-choice"><input type="${type}" ${name?`name="${name}"`:''} value="${esc(value)}"><span>${label}</span></label>`;
$('#ra-diets').innerHTML=dietLabels.map(([name,desc])=>choice('checkbox','',name,`<strong>${name}</strong><br><span class="text-xs">${desc}</span>`)).join('');
$('#ra-allergies').innerHTML=allergens.map(name=>choice('checkbox','',name,name)).join('');
$('#ra-budget').innerHTML=['Günstig','Normal','Großzügig','Offen'].map(x=>choice('radio','ra-budget',x,x)).join('');
$('#ra-leftovers').innerHTML=['Jeden Tag neu','Gerne für zwei Tage kochen','Egal / flexibel'].map(x=>choice('radio','ra-leftovers',x,x)).join('');
$('#ra-sport').innerHTML=sportLevels.map(([title,examples],i)=>`<div><div class="font-medium text-sm">${title}</div><p class="text-xs mb-2">Beispiele: ${examples}</p><div class="grid grid-cols-2 gap-2"><label>Häufigkeit<select id="ra-sport-f-${i}">${options(['Nein','1×/Woche','2×/Woche','3×/Woche','4–5×/Woche','Täglich'])}</select></label><label>Dauer je Einheit<select id="ra-sport-d-${i}">${options(['15 Min.','30 Min.','45 Min.','60 Min.','90+ Min.'])}</select></label></div></div>`).join('');
function renderRatings(target,names,type){$(target).innerHTML=names.map((name,i)=>`<div class="ra-rate"><div class="ra-rate-label text-sm">${name}</div>${[1,2,3,4,5].map(v=>`<button type="button" data-rate-type="${type}" data-rate-index="${i}" data-rate-value="${v}" aria-pressed="false" aria-label="${name}: ${v}">${v}</button>`).join('')}</div>`).join('');}
renderRatings('#ra-food-ratings',foodNames,'food');renderRatings('#ra-cuisine-ratings',cuisineNames,'cuisine');
$('#ra-meals').innerHTML=days.map((d,di)=>`<tr><th scope="row">${d}</th>${slots.map((s,si)=>`<td><button type="button" class="meal-toggle" data-day="${di}" data-meal="${si}" aria-pressed="false" aria-label="${d}: ${s}">−</button></td>`).join('')}</tr>`).join('');
$('#ra-times').innerHTML=slots.map((s,i)=>`<tr><th scope="row">${s}</th>${['15 Min.','30 Min.','45 Min.','60+ Min.','Zeit egal'].map(t=>`<td><input type="radio" name="ra-time-${i}" value="${t}" aria-label="${s}: ${t}"></td>`).join('')}</tr>`).join('');
$('#ra-meals').closest('.ra-panel').insertAdjacentHTML('beforeend','<label class="coverage-question"><input id="ra-whole-day" type="checkbox" checked>Die aktivierten Mahlzeiten decken meinen ganzen Tag ab.</label>');
$('#ra-status').setAttribute('aria-live','polite');
$('#ra-profile').firstElementChild.insertAdjacentHTML('afterend','<div class="ra-progress" role="progressbar" aria-label="Profilfortschritt" aria-valuemin="0" aria-valuemax="9" aria-valuenow="0"><div style="width:0%"></div></div>');
$$('.ra-section').forEach(section=>{const n=section.dataset.section,button=section.querySelector('.ra-head'),panel=section.querySelector('.ra-panel');button.id='ra-head-'+n;panel.id='ra-panel-'+n;button.setAttribute('aria-controls',panel.id);panel.setAttribute('aria-labelledby',button.id);});
const value=id=>$('#ra-'+id).value;
const checkedValues=selector=>$$(selector+':checked').map(e=>e.value);
function collect(){
 const p=blankProfile();
 p.body={age:value('age'),sex:value('sex'),height:value('height'),weight:value('weight'),goal:checkedValues('input[name="ra-goal"]')[0]||'',notes:value('body-notes')};
 p.movement={activity:value('activity'),workdays:value('workdays'),workhours:value('workhours'),commute:value('commute'),steps:value('steps'),sport:[0,1,2].map(i=>({frequency:value('sport-f-'+i),duration:value('sport-d-'+i)}))};
 p.diets=checkedValues('#ra-diets input');p.allergies=checkedValues('#ra-allergies input');
 for(const [k,target]of [['extraDiets','diet'],['extraAllergies','allergy'],['extraCuisines','cuisine']])p[k]=$$('#ra-'+target+'-extra .ra-tag').map(e=>e.dataset.value);
 p.foodRatings={...state.food};p.cuisineRatings={...state.cuisine};p.snacks=value('snacks');p.people=value('people');
 p.matrix=days.map((_,d)=>slots.map((_,s)=>$(`[data-day="${d}"][data-meal="${s}"]`).getAttribute('aria-pressed')==='true'));p.matrixTouched=profile.matrixTouched;
 p.times=Object.fromEntries(slots.map((s,i)=>[s,checkedValues(`input[name="ra-time-${i}"]`)[0]||'']));p.budget=checkedValues('input[name="ra-budget"]')[0]||'';p.leftovers=checkedValues('input[name="ra-leftovers"]')[0]||'';
 p.pantry=$$('#ra-pantry-list>div').map(row=>({name:row.querySelector('[data-pantry-name]').textContent,category:row.querySelector('select').value}));p.pantryVisited=state.visited.has(9);p.wholeDay=$('#ra-whole-day').checked;
 return p;
}
function updateProgress(){
 profile=collect();const done=completeness(profile),count=done.filter(Boolean).length;
 $('#ra-status').textContent=`${count} / 9 Bereiche`;
 $('.ra-progress').setAttribute('aria-valuenow',count);$('.ra-progress>div').style.width=`${count/9*100}%`;
 $$('.ra-section').forEach((s,i)=>{let marker=s.querySelector('.section-done');if(!marker){marker=document.createElement('span');marker.className='section-done';s.querySelector('.ra-head>span').appendChild(marker);}marker.textContent=done[i]?'vollständig':'';});
 // Incomplete profiles intentionally never disable calculation.
 $('#ra-finish').disabled=false;
}
function persist(){if(!savedEnabled)return;try{localStorage.setItem(storageKey,JSON.stringify(profile));}catch{savedEnabled=false;toast('Speichern ist in diesem Browser nicht verfügbar. Profil als Datei herunterladen.');}}
function changed(){updateProgress();persist();if(plan){$('#breadcrumb').textContent='Deine Planung / Profil geändert';$('#ra-finish-note').textContent='Dein Profil wurde geändert. Erneut berechnen, um den Wochenplan zu aktualisieren.';$('#ra-finish-note').classList.remove('hidden');}}
function renderTag(container,text){const tag=document.createElement('span');tag.className='ra-tag';tag.dataset.value=text;const label=document.createElement('span');label.textContent=text;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',text+' entfernen');remove.addEventListener('click',()=>{tag.remove();changed();});tag.append(label,remove);$(container).appendChild(tag);}
function addTag(input,container){const text=$(input).value.trim().slice(0,300);if(!text)return;if($$(container+' .ra-tag').some(x=>x.dataset.value===text)){toast('Dieser Eintrag ist schon vorhanden.');return;}renderTag(container,text);$(input).value='';changed();}
$('#ra-add-diet').addEventListener('click',()=>addTag('#ra-other-diet','#ra-diet-extra'));
$('#ra-add-allergy').addEventListener('click',()=>{const text=value('other-allergy').trim();if(text){const none=$$('#ra-allergies input').find(e=>e.value==='Keine bekannt');none.checked=false;addTag('#ra-other-allergy','#ra-allergy-extra');}});
$('#ra-add-cuisine').addEventListener('click',()=>{if(!value('other-cuisine-score')){toast('Bitte eine Bewertung für die zusätzliche Küche auswählen.');return;}if(value('other-cuisine').trim()){renderTag('#ra-cuisine-extra',value('other-cuisine').trim()+' · '+value('other-cuisine-score')+'/5');$('#ra-other-cuisine').value='';$('#ra-other-cuisine-score').value='';changed();}});
function addPantry(name,category='Optional vorhanden'){
 const row=document.createElement('div');row.className='grid gap-2 sm:grid-cols-[1fr_auto]';
 row.innerHTML=`<span class="text-sm" data-pantry-name>${esc(name)}</span><div class="flex gap-2"><select aria-label="Kategorie für ${esc(name)}">${options(['Grundvorrat','Muss verbraucht werden','Optional vorhanden'])}</select><button type="button" class="ra-small-button" aria-label="${esc(name)} entfernen">×</button></div>`;
 row.querySelector('select').value=category;row.querySelector('button').addEventListener('click',()=>{row.remove();changed();});$('#ra-pantry-list').appendChild(row);
}
$('#ra-add-pantry').addEventListener('click',()=>{const name=value('pantry-input').trim().slice(0,200);if(!name)return;addPantry(name);$('#ra-pantry-input').value='';state.visited.add(9);changed();});
for(const id of ['other-diet','other-allergy','pantry-input'])$('#ra-'+id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#ra-add-'+({'other-diet':'diet','other-allergy':'allergy','pantry-input':'pantry'}[id])).click();}});
$$('.ra-head').forEach(button=>button.addEventListener('click',()=>{const section=button.closest('.ra-section'),open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',open);section.querySelector('.ra-panel').classList.toggle('hidden',!open);button.querySelector('.ra-chevron').textContent=open?'▾':'▸';if(open)state.visited.add(Number(section.dataset.section));changed();}));
$('#ra-profile').addEventListener('click',e=>{
 const rating=e.target.closest('[data-rate-type]');if(rating){const type=rating.dataset.rateType,names=type==='food'?foodNames:cuisineNames,name=names[Number(rating.dataset.rateIndex)],score=Number(rating.dataset.rateValue);state[type][name]=score;$$(`[data-rate-type="${type}"][data-rate-index="${rating.dataset.rateIndex}"]`).forEach(b=>{const active=b===rating;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});changed();}
 const cell=e.target.closest('[data-day]');if(cell){cell.setAttribute('aria-pressed',cell.getAttribute('aria-pressed')!=='true');cell.textContent=cell.getAttribute('aria-pressed')==='true'?'✓':'−';profile.matrixTouched=true;changed();}
});
$('#ra-allergies').addEventListener('change',e=>{if(e.target.checked&&e.target.value==='Keine bekannt'){$$('#ra-allergies input').forEach(x=>{if(x!==e.target)x.checked=false;});$('#ra-allergy-extra').replaceChildren();}else if(e.target.checked){$$('#ra-allergies input').find(x=>x.value==='Keine bekannt').checked=false;}changed();});
$('#ra-diets').addEventListener('change',e=>{if(e.target.checked&&e.target.value!=='Ayurvedisch'){$$('#ra-diets input').forEach(x=>{if(x!==e.target&&x.value!=='Ayurvedisch')x.checked=false;});}changed();});
$('#ra-profile').addEventListener('input',changed);$('#ra-profile').addEventListener('change',changed);
function setCell(d,s,checked){const b=$(`[data-day="${d}"][data-meal="${s}"]`);b.setAttribute('aria-pressed',checked);b.textContent=checked?'✓':'−';}
function copyDay(source,targets){for(const d of targets)for(let s=0;s<4;s++)setCell(d,s,$(`[data-day="${source}"][data-meal="${s}"]`).getAttribute('aria-pressed')==='true');profile.matrixTouched=true;changed();}
$('#ra-copy-all').addEventListener('click',()=>copyDay(0,[1,2,3,4,5,6]));$('#ra-copy-week').addEventListener('click',()=>copyDay(0,[1,2,3,4]));$('#ra-copy-weekend').addEventListener('click',()=>copyDay(5,[6]));$('#ra-reset-meals').addEventListener('click',()=>{for(let d=0;d<7;d++)for(let s=0;s<4;s++)setCell(d,s,false);profile.matrixTouched=true;changed();});
$('#ra-movement-button').addEventListener('click',()=>{profile=collect();$('#ra-movement-summary').textContent=[profile.movement.activity||'Tätigkeit offen',profile.movement.workdays?profile.movement.workdays+' Arbeitstage':'Arbeitstage offen',profile.movement.workhours||'Arbeitszeit offen','Arbeitsweg: '+(profile.movement.commute||'offen'),profile.movement.steps?profile.movement.steps+' Schritte/Tag':'Schritte unbekannt',...profile.movement.sport.map((s,i)=>sportLevels[i][0]+': '+s.frequency+(s.frequency!=='Nein'?' à '+s.duration:''))].join(' · ');$('#ra-movement-summary').classList.remove('hidden');$('#ra-movement-summary').classList.add('movement-summary');});
function restore(p){
 profile=p;state.food={...p.foodRatings};state.cuisine={...p.cuisineRatings};state.visited=new Set(p.pantryVisited?[1,9]:[1]);
 for(const[id,k]of [['age','age'],['sex','sex'],['height','height'],['weight','weight'],['body-notes','notes']])$('#ra-'+id).value=p.body[k]??'';
 $$('input[name="ra-goal"]').forEach(x=>x.checked=x.value===p.body.goal);
 for(const[id,k]of [['activity','activity'],['workdays','workdays'],['workhours','workhours'],['commute','commute'],['steps','steps']])$('#ra-'+id).value=p.movement[k]??'';
 [0,1,2].forEach(i=>{$('#ra-sport-f-'+i).value=p.movement.sport[i]?.frequency||'Nein';$('#ra-sport-d-'+i).value=p.movement.sport[i]?.duration||'15 Min.';});
 $$('#ra-diets input').forEach(x=>x.checked=p.diets.includes(x.value));$$('#ra-allergies input').forEach(x=>x.checked=p.allergies.includes(x.value));
 for(const[target,key]of [['diet','extraDiets'],['allergy','extraAllergies'],['cuisine','extraCuisines']]){$('#ra-'+target+'-extra').replaceChildren();p[key].forEach(t=>renderTag('#ra-'+target+'-extra',t));}
 $$('[data-rate-type]').forEach(x=>{const names=x.dataset.rateType==='food'?foodNames:cuisineNames,v=state[x.dataset.rateType][names[Number(x.dataset.rateIndex)]],active=v===Number(x.dataset.rateValue);x.classList.toggle('active',active);x.setAttribute('aria-pressed',active);});
 $('#ra-snacks').value=p.snacks;$('#ra-people').value=p.people;$('#ra-whole-day').checked=p.wholeDay;
 days.forEach((_,d)=>slots.forEach((_,s)=>setCell(d,s,p.matrix[d][s])));
 slots.forEach((s,i)=>$$(`input[name="ra-time-${i}"]`).forEach(x=>x.checked=p.times[s]===x.value));
 $$('input[name="ra-budget"]').forEach(x=>x.checked=p.budget===x.value);$$('input[name="ra-leftovers"]').forEach(x=>x.checked=p.leftovers===x.value);
 $('#ra-pantry-list').replaceChildren();p.pantry.forEach(x=>addPantry(x.name,x.category));updateProgress();
}
function calculate(){profile=collect();persist();plan=planWeek(profile,seed);checkedShopping.clear();selectedDay=0;renderPlan();renderShopping();view('woche');toast('Berechnet. Offene Angaben findest du bei den Annahmen.');}
['ra-finish','sidebar-calculate','empty-calculate','shopping-calculate'].forEach(id=>$('#'+id).addEventListener('click',calculate));
$('#regenerate').addEventListener('click',()=>{seed++;calculate();});
function view(name){if(!['profil','woche','rezepte','einkauf'].includes(name))name='profil';currentView=name;$$('.view').forEach(el=>el.hidden=el.id!=='view-'+name);$$('[data-view]').forEach(b=>{const active=b.dataset.view===name;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#breadcrumb').textContent='Deine Planung / '+({profil:'Mein Profil',woche:'Meine Woche',rezepte:'Rezepte entdecken',einkauf:'Einkaufsliste'}[name]);history.replaceState(null,'','#'+name);if(name==='rezepte')loadCatalog();window.scrollTo({top:0,behavior:'instant'});}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));$('.brand').addEventListener('click',e=>{e.preventDefault();view('profil');});
function renderPlan(){
 $('#plan-empty').hidden=!(!plan);$('#plan-content').hidden=!plan;if(!plan)return;
 const {energy}=plan;const actual=plan.daily.reduce((s,d)=>s+d.kcal,0)/7;
 $('#energy-summary').innerHTML=`<div class="energy-stat"><span>${energy.personal?'Geschätzter Tagesbedarf':'Vorläufiger Planungswert'}</span><strong>${format(energy.target)} <small>kcal</small></strong><small>${energy.rest?`Bereich ca. ${format(energy.range[0])}–${format(energy.range[1])} kcal`:'Keine persönliche Bedarfsaussage'}</small></div><div class="energy-stat"><span>Tatsächlich geplant / Tag</span><strong>${format(round(actual,10))} <small>kcal</small></strong><small>Durchschnitt pro Person über 7 Tage</small></div><div class="energy-stat"><span>Diese Woche</span><strong>${plan.entries.length} <small>Mahlzeiten</small></strong><small>Für ${plan.people} ${plan.people===1?'Person':'Personen'}</small></div>`;
 $('#plan-conclusion').textContent=plan.entries.length?'Die ausgewählten Mahlzeiten verbinden Rezept, passende Beilagen und Ergänzungen. '+(plan.wholeDay?'Die aktivierten Mahlzeiten sollen den ganzen Tag abdecken. ':'Weitere Mahlzeiten außerhalb dieses Plans sind nicht bilanziert. ')+(plan.preliminary?'Allergieangaben sind noch ungeklärt oder benötigen zusätzliche Prüfung. Der Plan bleibt vorläufig. ':'Die hinterlegten Ausschlüsse wurden auf Zutatenebene berücksichtigt; Produktetiketten bleiben maßgeblich. ')+`Der berechenbare Bestand umfasst ${format(recipes.length)} Mahlzeiten. Eine vollständige Mikronährstoffdeckung wird nicht zugesichert.`:'Die Energieabschätzung ist fertig. Ein passender Mahlzeitenplan ist mit der aktuellen Auswahl nicht vollständig möglich. Die Gründe stehen unten.';
 $('#assumptions-title').textContent=`${energy.assumptions.length} Annahmen und offene Angaben`;
 $('#assumptions-list').innerHTML='<ul>'+energy.assumptions.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>';
 $('#assumptions-box').open=false;
 $('#plan-issues').innerHTML=[...energy.warnings,...plan.issues].map(x=>`<p class="warning">${esc(x)}</p>`).join('');
 $('#day-tabs').innerHTML=days.map((d,i)=>`<button class="day-tab" id="day-${i}" role="tab" aria-controls="day-panel" aria-selected="${i===selectedDay}" data-select-day="${i}">${d.slice(0,2)}<span>${format(round(plan.daily[i].kcal,10))} kcal</span></button>`).join('');
 renderDay();
 const total=plan.daily.reduce((acc,d)=>{for(const k of ['kcal','protein','fat','carbs','fibre'])acc[k]+=d[k];return acc;},{kcal:0,protein:0,fat:0,carbs:0,fibre:0});
 $('#week-balance').innerHTML=`<h2>Deine Woche in Zahlen</h2><div class="balance-scroll"><table class="balance-table"><thead><tr><th>Tag</th><th>kcal</th><th>Protein</th><th>Fett</th><th>Kohlenhydrate</th></tr></thead><tbody>${plan.daily.map(d=>`<tr><th scope="row">${d.day}</th><td>${format(round(d.kcal,10))}</td><td>${round(d.protein)} g</td><td>${round(d.fat)} g</td><td>${round(d.carbs)} g</td></tr>`).join('')}<tr><th scope="row">Ø pro Tag</th><td>${format(round(total.kcal/7,10))}</td><td>${round(total.protein/7)} g</td><td>${round(total.fat/7)} g</td><td>${round(total.carbs/7)} g</td></tr></tbody></table></div><p class="muted">Alle Werte pro Person, einschließlich aller geplanten Komponenten. Ballaststoffe: erfasste Teilsumme im Mittel ${round(total.fibre/7)} g/Tag. Fehlende Werte wurden nicht als null interpretiert. Jod und Vitamin D sind nicht vollständig bilanziert.</p><p class="muted">Mahlzeiten werden auf den persönlichen Planungswert skaliert. Für weitere Personen wird dieselbe Portion angenommen. Individuelle Bedarfe weiterer Personen sind nicht bekannt.</p>`;
}
function mealCard(entry,index){
 const n=entry.nutrition;const top=entry.mainIngredientNames.slice(0,4).map(name=>`${format(round(entry.ingredients[name]))} ${unitOf(name)} ${esc(name)}`);
 const extras=Object.keys(entry.ingredients).filter(name=>!entry.mainIngredientNames.includes(name)&&!['Wasser','Salz'].includes(name));
 return `<article class="meal-card"><div class="meal-banner"><span class="tiny-label">${entry.slot.toLocaleUpperCase('de')}</span><span class="pill">${entry.leftover?'Vom Vortag':entry.prepareDouble?'Für zwei Tage kochen':entry.cuisine}</span></div><div class="meal-body"><h3>${esc(entry.name)}</h3><p>${entry.prepareDouble?'Heute doppelt zubereiten. ':''}${entry.leftover?'Bereits am Vortag zubereitet. ':''}Eine Portion pro Person · Zeit nicht dokumentiert</p><ul class="meal-details">${top.map(t=>`<li>${t}</li>`).join('')}</ul>${extras.length?`<p>Außerdem ${extras.slice(0,8).map(esc).join(', ')}${extras.length>8?' und weitere':''}.</p>`:''}<div class="macro-row"><span><strong>${format(round(n.kcal,10))}</strong> kcal</span><span><strong>${round(n.protein)} g</strong> Protein</span><span><strong>${round(n.fat)} g</strong> Fett</span><span><strong>${round(n.carbs)} g</strong> KH</span></div><div class="meal-actions"><button class="text-button" data-meal-detail="${index}">Zutaten &amp; Zubereitung <span aria-hidden="true">↗</span></button></div></div></article>`;
}
function renderDay(){
 if(!plan)return;const daily=plan.daily[selectedDay];$('#day-panel').setAttribute('aria-labelledby','day-'+selectedDay);
 $('#day-panel').innerHTML=`<div class="day-heading"><h2>${days[selectedDay]}</h2><span class="muted">${format(round(daily.kcal,10))} kcal pro Person</span></div><div class="meal-grid">${plan.entries.map((e,i)=>e.dayIndex===selectedDay?mealCard(e,i):'').join('')||'<p class="muted">Für diesen Tag ist keine passende Mahlzeit geplant.</p>'}</div>`;
}
$('#day-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-select-day]');if(!b)return;selectedDay=Number(b.dataset.selectDay);$$('[data-select-day]').forEach(x=>x.setAttribute('aria-selected',Number(x.dataset.selectDay)===selectedDay));renderDay();});
$('#day-tabs').addEventListener('keydown',e=>{const b=e.target.closest('[data-select-day]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();selectedDay=e.key==='Home'?0:e.key==='End'?6:(selectedDay+(e.key==='ArrowRight'?1:6))%7;$('#day-'+selectedDay).click();$('#day-'+selectedDay).focus();});
$('#day-panel').addEventListener('click',e=>{const b=e.target.closest('[data-meal-detail]');if(b)showMeal(plan.entries[Number(b.dataset.mealDetail)]);});
function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function showMeal(entry){const n=entry.nutrition;showDialog(entry.name,`<div class="dialog-copy"><p class="muted">${entry.day} · ${entry.slot} · Rezept ${esc(entry.reference)} · Mengen auf deinen Bedarf umgerechnet</p><h3>Zutaten für ${plan.people} ${plan.people===1?'Person':'Personen'}</h3>${entry.prepareDouble?'<p>Für morgen dieselben Mengen zusätzlich zubereiten. Die Einkaufsliste enthält bereits beide Tage.</p>':''}<ul class="ingredient-list">${Object.entries(entry.ingredients).map(([name,g])=>`<li>${format(round(g*plan.people))} ${unitOf(name)} ${esc(name)}</li>`).join('')}</ul><p class="muted">Mengen wie eingekauft bzw. abgewogen (Getreide und Hülsenfrüchte roh, wenn nicht anders angegeben). Knochen, Lorbeer, Frittier- und Kochwasser zählen nur anteilig zu den Nährwerten. Salz nach Geschmack.</p><h3>Zubereitung</h3><p>${esc(entry.instructions)}</p><p class="muted">Die Zutatenmengen sind skaliert; Flüssigkeit und Formgröße bei der Zubereitung entsprechend anpassen. Zeitangaben fehlen in den Quellen. Die Zubereitung beschreibt die Originalmenge.</p><h3>Geschätzte Nährwerte pro Person</h3><p>${format(round(n.kcal,10))} kcal · ${round(n.protein)} g Protein · ${round(n.fat)} g Fett · ${round(n.carbs)} g Kohlenhydrate</p><p class="muted">Calcium rechnerisch ${round(n.calcium)} mg; Fehlende Mikronährwerte und Garverluste sind nicht vollständig erfasst.</p><p class="muted">Enthaltene bekannte Allergene: ${esc([...new Set(Object.keys(entry.ingredients).flatMap(name=>foods[name].allergens))].join(', ')||'keine in der Zutatenzuordnung')}. Produktbestandteile und Spurenhinweise separat prüfen.</p></div>`);}
function renderShopping(){
 $('#shopping-empty').hidden=Boolean(plan?.entries.length);$('#shopping-content').hidden=!plan?.entries.length;if(!plan?.entries.length)return;
 const items=shoppingList(plan,profile);$('#shopping-intro').textContent=`Für ${plan.people} ${plan.people===1?'Person':'Personen'} und ${plan.entries.length} Mahlzeiten. Angezeigt werden benötigte Verbrauchsmengen. Bei Vorräten bitte die vorhandene Menge prüfen.`;
 $('#shopping-list').innerHTML=items.map((item,i)=>`<label class="shopping-item"><input type="checkbox" data-shopping="${i}" ${checkedShopping.has(item.name)?'checked':''}><span class="item-name">${esc(item.name)}${item.pantry.length?`<small>${esc(item.pantry.join(', '))} · vorhandene Menge prüfen</small>`:''}</span><span class="quantity">${format(round(item.grams))} ${item.unit}</span></label>`).join('');
 $('#shopping-progress-label').textContent=`${checkedShopping.size} von ${items.length} abgehakt`;
}
$('#shopping-list').addEventListener('change',e=>{const i=e.target.dataset.shopping;if(i==null)return;const item=shoppingList(plan,profile)[Number(i)];if(e.target.checked)checkedShopping.add(item.name);else checkedShopping.delete(item.name);$('#shopping-progress-label').textContent=`${checkedShopping.size} von ${shoppingList(plan,profile).length} abgehakt`;});
$('#uncheck-shopping').addEventListener('click',()=>{checkedShopping.clear();renderShopping();});
async function loadCatalog(){
 if(catalog){renderRecipes();return;}
 $('#recipe-count').textContent='Rezeptsammlung wird geladen …';
 try{const response=await fetch(new URL('./catalog.json',import.meta.url));if(!response.ok)throw Error('HTTP '+response.status);catalog=await response.json();const cuisines=[...new Set(catalog.map(r=>r.cuisine))].sort((a,b)=>a.localeCompare(b,'de'));$('#recipe-cuisine').innerHTML='<option value="">Alle Küchen</option>'+cuisines.map(c=>`<option>${esc(c)}</option>`).join('');renderRecipes();}
 catch{$('#recipe-count').textContent='Die große Sammlung konnte nicht geladen werden. Berechenbare Mahlzeiten bleiben verfügbar.';$('#calculable-only').checked=true;renderRecipes();}
}
function filteredRecipes(){
 const query=$('#recipe-search').value.trim().toLocaleLowerCase('de'),cuisine=$('#recipe-cuisine').value;
 return ($('#calculable-only').checked?recipes:catalog||recipes).filter(r=>(!query||(r.name+' '+r.cuisine).toLocaleLowerCase('de').includes(query))&&(!cuisine||r.cuisine===cuisine));
}
function renderRecipes(){const filtered=filteredRecipes();$('#recipe-count').textContent=`${format(filtered.length)} Treffer · ${format(recipes.length)} berechenbare Mahlzeiten insgesamt`;$('#recipe-grid').innerHTML=filtered.slice(0,recipeLimit).map((r,i)=>`<button class="recipe-card" data-recipe-index="${i}"><span class="tiny-label">${esc(r.cuisine)}</span><h3>${esc(r.name)}</h3><span class="muted">${r.calculable===false?'Zum Stöbern · nicht im Wochenplan':'Mengen & Nährwerte berechenbar'} <span aria-hidden="true">↗</span></span></button>`).join('')||'<p>Keine passenden Rezepte gefunden.</p>';$('#more-recipes').hidden=recipeLimit>=filtered.length;}
$('#recipe-search').addEventListener('input',()=>{recipeLimit=30;renderRecipes();});$('#recipe-cuisine').addEventListener('change',()=>{recipeLimit=30;renderRecipes();});$('#calculable-only').addEventListener('change',()=>{recipeLimit=30;renderRecipes();});$('#more-recipes').addEventListener('click',()=>{recipeLimit+=30;renderRecipes();});
$('#recipe-grid').addEventListener('click',e=>{const b=e.target.closest('[data-recipe-index]');if(!b)return;const r=filteredRecipes()[Number(b.dataset.recipeIndex)];const ingredientText=typeof r.ingredients==='string'?r.ingredients:Object.entries(r.ingredients).map(([n,g])=>`${g} g ${n}`).join('; ');showDialog(r.name,`<div class="dialog-copy"><p class="muted">${esc(r.cuisine)} · ${esc(r.reference||r.id)}${r.yield?' · Originalmenge für '+esc(r.yield)+' Portionen':''}</p><h3>Zutaten</h3><p>${esc(ingredientText)}</p><h3>Zubereitung</h3><p>${esc(r.instructions)}</p>${r.sides?`<p>Passende Beilagen aus der Quelle: ${esc(r.sides)}</p>`:''}<p class="warning">${r.calculable===false?'Dieses Rezept ist zum Stöbern verfügbar. Es ist eine Nachspeise, Beilage, ein Grundrezept oder Getränk bzw. nicht alle Zutaten haben Nährwerte; deshalb wird es nicht automatisch verplant.':'Dieses Rezept gehört zum berechenbaren Bestand und kann im Wochenplan vorkommen.'}${r.allergens?.length?' Enthaltene Hauptallergene laut Zutatenzuordnung (ungeprüft): '+esc(r.allergens.join(', '))+'.':''}</p><p class="muted">${esc(r.note||'')}</p></div>`);});
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function planText(){if(!plan)return '';const lines=['# Dein Wochenplan','',`Für ${plan.people} Personen. Zielwert pro Person: ca. ${plan.energy.target} kcal/Tag.`, '', '## Fazit','', $('#plan-conclusion').textContent,'','## Annahmen','',...plan.energy.assumptions.map(x=>'- '+x),'',...plan.energy.warnings.map(x=>'- '+x),...plan.issues.map(x=>'- '+x)];for(const e of plan.entries){const n=e.nutrition;lines.push('',`## ${e.day} · ${e.slot}: ${e.name}`,'',`${round(n.kcal,10)} kcal · Protein ${round(n.protein)} g · Fett ${round(n.fat)} g · Kohlenhydrate ${round(n.carbs)} g pro Person.`,'',...Object.entries(e.ingredients).map(([name,g])=>`- ${round(g*plan.people)} ${unitOf(name)} ${name}`),'',e.instructions||'',e.leftover?'Vom Vortag.':e.prepareDouble?'Doppelte Menge für morgen zubereiten.':'Frisch zubereiten.');}lines.push('','## Einkaufsliste','',...shoppingList(plan,profile).map(x=>`- ${round(x.grams)} ${x.unit} ${x.name}${x.pantry.length?' · Vorrat prüfen':''}`),'','Nährwertgrundlage: CoFID 2021. Energieformel: Mifflin-St Jeor. Fehlende Nährwerte und Kochzeiten werden nicht erfunden.');return lines.join('\n');}
$('#download-plan').addEventListener('click',()=>{if(!plan){toast('Bitte zuerst berechnen.');return;}download('recipe-assistant-wochenplan.md',planText());});
$('#download-shopping').addEventListener('click',()=>{if(!plan){toast('Bitte zuerst berechnen.');return;}download('recipe-assistant-einkauf.txt',shoppingList(plan,profile).map(x=>`${checkedShopping.has(x.name)?'[x]':'[ ]'} ${round(x.grams)} ${x.unit} ${x.name}${x.pantry.length?' · Vorrat prüfen':''}`).join('\n'));});
$('#print-plan').addEventListener('click',()=>window.print());
window.addEventListener('beforeprint',()=>{if(!plan||currentView!=='woche')return;$('#day-panel').innerHTML=days.map((d,di)=>`<div class="day-heading"><h2>${d}</h2></div><div class="meal-grid">${plan.entries.map((e,i)=>e.dayIndex===di?mealCard(e,i):'').join('')}</div>`).join('');});window.addEventListener('afterprint',()=>{if(plan)renderDay();});
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function openData(){$('#storage-status').textContent=savedEnabled?'Profil wird auf diesem Gerät gespeichert.':'Profil wird nicht dauerhaft auf diesem Gerät gespeichert.';$('#data-dialog').showModal();}
$('#save-profile').addEventListener('click',()=>{profile=collect();savedEnabled=true;persist();if(savedEnabled){$('#save-profile').textContent='Profil gespeichert';toast('Profil auf diesem Gerät gespeichert. Änderungen werden lokal übernommen.');}});
$('#open-data').addEventListener('click',openData);$('#close-data').addEventListener('click',()=>$('#data-dialog').close());$('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());
for(const id of ['detail-dialog','data-dialog'])$('#'+id).addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
$('#export-profile').addEventListener('click',()=>download('recipe-assistant-profil.json',JSON.stringify(collect(),null,2),'application/json'));
$('#import-profile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('Datei ist zu groß.');const p=validateImportedProfile(JSON.parse(await file.text()));restore(p);plan=null;renderPlan();renderShopping();persist();$('#data-dialog').close();view('profil');toast('Profil geladen. Bitte berechnen, um die Woche zu erstellen.');}catch(error){toast('Profil konnte nicht geladen werden: '+error.message);}finally{e.target.value='';}});
$('#forget-profile').addEventListener('click',()=>{try{localStorage.removeItem(storageKey);savedEnabled=false;$('#save-profile').textContent='Profil merken';$('#storage-status').textContent='Gespeichertes Profil gelöscht. Aktuelle Eingaben bleiben bis zum Schließen im Browser geöffnet.';toast('Die gespeicherte Kopie auf diesem Gerät wurde gelöscht.');}catch{toast('Browserspeicher ist nicht zugänglich.');}});
$('#about-data').addEventListener('click',()=>showDialog('Quellen & Berechnung',`<div class="dialog-copy"><h3>Was kann diese Version?</h3><p>Die Sammlung enthält 2.626 Rezepte. ${format(recipes.length)} davon – Hauptgerichte und Snacks, bei denen jede Zutat einem Eintrag der Nährwerttabelle zugeordnet ist – werden für den Wochenplan berechnet. Nachspeisen, Beilagen, Grundrezepte und Getränke sind zum Stöbern da. Zutatenzuordnung und Allergene wurden maschinell erstellt und sind nicht fachlich geprüft.</p><h3>Fehlende Angaben</h3><p>Berechnen bleibt immer möglich. Ohne geeignete vollständige Körperdaten dienen 2.000 kcal als sichtbarer Referenzwert. Fehlende Allergieangaben gelten als ungeklärt. Nicht prüfbare individuelle Allergien können die Rezeptauswahl verhindern, während die Energieabschätzung weiter angezeigt wird.</p><h3>Nährwerte</h3><p>Berechnung aus essbaren Zutatenmengen und <a href="https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid" target="_blank" rel="noopener noreferrer">CoFID 2021</a>. Keine BLS-Berechnung. Fehlende Werte werden als fehlend geführt. Mikronährstoffe und Garverluste sind nicht vollständig erfasst. Für manche seltene Zutaten wird ein ähnliches Lebensmittel der Tabelle verwendet.</p><h3>Energie</h3><p><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer">Mifflin-St Jeor</a> mit Alter, Körpergröße, Gewicht und Formelvariante. Aktivität wird mit einem groben PAL-Rahmen berücksichtigt. Beruf, Arbeitszeit, Schritte und Sport sind Näherungen, keine Messwerte. Fehlendes Geschlecht ergibt einen Bereich aus beiden Formelvarianten.</p><h3>Ausgewogenheit und Sicherheit</h3><p>Orientierung an den <a href="https://www.dge.de/gesunde-ernaehrung/gut-essen-und-trinken/dge-ernaehrungskreis/" target="_blank" rel="noopener noreferrer">DGE-Empfehlungen</a>. Sicherheit vor Vorlieben, vollständige Mahlzeiten vor isolierten Rezeptkernen. Maximal 300 g Fleisch pro Person und Woche im Plan. Jod und Vitamin D sind nicht vollständig bilanziert. Ayurvedisch dient ausschließlich als kulinarische Orientierung. Keine Diagnosen oder therapeutischen Supplementdosierungen.</p><h3>Datenschutz</h3><p>Keine Analyse- oder Werbedienste, keine KI-Anfragen und kein Benutzerkonto. Eingaben bleiben im Browser. Nach „Profil merken“ werden sie im lokalen Browserspeicher abgelegt. Exportierte Profildateien enthalten persönliche Angaben; bewahre sie entsprechend auf.</p></div>`));
try{const saved=localStorage.getItem(storageKey);if(saved){restore(validateImportedProfile(JSON.parse(saved)));savedEnabled=true;$('#save-profile').textContent='Profil gespeichert';}else updateProgress();}catch{updateProgress();toast('Gespeichertes Profil konnte nicht geladen werden. Du kannst trotzdem berechnen.');}
view(location.hash.slice(1)||'profil');
